static const EmbeddedEntry embedded_table[] = {
    {"runtime.s", (const char*)runtime_s_data, sizeof(runtime_s_data) - 1},
    {"fundamental.huki", (const char*)fundamental_huki_data, sizeof(fundamental_huki_data) - 1},
    {"fundamental.hu", (const char*)fundamental_huki_data, sizeof(fundamental_huki_data) - 1},
    {"fundamental.suki", (const char*)fundamental_suki_data, sizeof(fundamental_suki_data) - 1},
    {"fundamental.su", (const char*)fundamental_suki_data, sizeof(fundamental_suki_data) - 1},
    {"math.huki", (const char*)math_huki_data, sizeof(math_huki_data) - 1},
    {"math.hu", (const char*)math_huki_data, sizeof(math_huki_data) - 1},
    {"math.suki", (const char*)math_suki_data, sizeof(math_suki_data) - 1},
    {"math.su", (const char*)math_suki_data, sizeof(math_suki_data) - 1},
    {"string.huki", (const char*)string_huki_data, sizeof(string_huki_data) - 1},
    {"string.hu", (const char*)string_huki_data, sizeof(string_huki_data) - 1},
    {"string.suki", (const char*)string_suki_data, sizeof(string_suki_data) - 1},
    {"string.su", (const char*)string_suki_data, sizeof(string_suki_data) - 1},
    {"c.huki", (const char*)c_huki_data, sizeof(c_huki_data) - 1},
    {"c.hu", (const char*)c_huki_data, sizeof(c_huki_data) - 1},
    {NULL, NULL, 0}
};

const char* get_embedded_file(const char* name, size_t* out_len) {
    if (!name) return NULL;
    const char* p = strrchr(name, '/');
    if (p) name = p + 1;
    const char* p2 = strrchr(name, '\\');
    if (p2) name = p2 + 1;

    for (int i = 0; embedded_table[i].name != NULL; i++) {
        if (strcmp(embedded_table[i].name, name) == 0) {
            if (out_len) *out_len = embedded_table[i].length;
            return embedded_table[i].content;
        }
    }
    return NULL;
}

int has_embedded_file(const char* name) {
    return (get_embedded_file(name, NULL) != NULL);
}

int extract_embedded_runtime(char* out_path, size_t max_len) {
    const char* content = get_embedded_file("runtime.s", NULL);
    if (!content) return 0;

    const char* tmp = getenv("TEMP");
    if (!tmp) tmp = getenv("TMP");
    if (!tmp) tmp = ".";
    snprintf(out_path, max_len, "%s\\itsuki_runtime.s", tmp);

    FILE* f = fopen(out_path, "wb");
    if (!f) return 0;
    fputs(content, f);
    fclose(f);
    return 1;
}
